    pose proof ot_itinerary as (_ & IT & _ & _ & SCALL & _). apply (f_equal (fun t => snd (snd (snd (fst t))))) in IT || idtac.
    tblk rH factsH scr0 AMEMCPY_RET srH0 knH0 259%nat (ENV vals) M R msF mo HR HK ltac:(constructor) OK RS.
